using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using CampaignDemo;
public static class BoldSymbolsAndPVEInstaller {
 const string Root="Assets/Game/UnitLibrary/Sprites/";
 const string Source="Assets/Game/UnitLibrary/SourceSymbolsBold/";
 static readonly string[] Roles={"Infantry","Engineer","Scout","Tank","Artillery","MountainInfantry","PersonnelCarrier","TransportTruck"};
 static readonly string[] Labels={"士兵","工兵","侦察兵","坦克","炮兵","山地步兵","运兵车","资源运输车"};
 static readonly string[] Grades={"Squad","Platoon","Company","Battalion","Regiment"},ChineseGrades={"班","排","连","营","团"};
 static readonly List<string> checks=new List<string>();
 static T Load<T>(string path)where T:UnityEngine.Object{var item=AssetDatabase.LoadAssetAtPath<T>(path);if(item==null)throw new Exception("Missing "+path);return item;}
 static Rect Body(Texture2D texture){var colors=texture.GetPixels32();int xmin=texture.width,ymin=texture.height,xmax=-1,ymax=-1;for(int y=0;y<texture.height*.75f;y++)for(int x=0;x<texture.width;x++)if(colors[y*texture.width+x].a>=128){xmin=Mathf.Min(xmin,x);xmax=Mathf.Max(xmax,x);ymin=Mathf.Min(ymin,y);ymax=Mathf.Max(ymax,y);}if(xmax<0)throw new Exception("Empty image");return new Rect(xmin,ymin,xmax-xmin+1,ymax-ymin+1);}
 static Rect BodyAt(string path){var texture=new Texture2D(2,2);texture.LoadImage(File.ReadAllBytes(path));var body=Body(texture);UnityEngine.Object.DestroyImmediate(texture);return body;}
 public static float VisibleWidth(Sprite sprite){return sprite==null?0:BodyAt(AssetDatabase.GetAssetPath(sprite)).width/sprite.pixelsPerUnit;}
 static Sprite Replace(string path,string source,float desiredWidth){string guid=AssetDatabase.AssetPathToGUID(path);File.Copy(source,path,true);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);var texture=new Texture2D(2,2);texture.LoadImage(File.ReadAllBytes(path));var body=Body(texture);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.spritePixelsPerUnit=body.width/desiredWidth;importer.mipmapEnabled=false;importer.alphaIsTransparency=true;importer.textureCompression=TextureImporterCompression.Uncompressed;var settings=new TextureImporterSettings();importer.ReadTextureSettings(settings);settings.spriteAlignment=(int)SpriteAlignment.Custom;settings.spritePivot=new Vector2(body.center.x/texture.width,body.center.y/texture.height);importer.SetTextureSettings(settings);importer.SaveAndReimport();UnityEngine.Object.DestroyImmediate(texture);if(!string.IsNullOrEmpty(guid)&&guid!=AssetDatabase.AssetPathToGUID(path))throw new Exception("Changed asset GUID "+path);var sprite=Load<Sprite>(path);if(Mathf.Abs(VisibleWidth(sprite)-desiredWidth)>.001f)throw new Exception("Changed physical width "+path);return sprite;}
 static AIBehaviorProfile Profile(string name,bool enabled){var path="Assets/Game/Data/AI/"+name+".asset";var profile=AssetDatabase.LoadAssetAtPath<AIBehaviorProfile>(path);if(profile==null){profile=ScriptableObject.CreateInstance<AIBehaviorProfile>();AssetDatabase.CreateAsset(profile,path);}profile.patrol=profile.reinforcement=profile.artillery=profile.cityRelief=profile.recovery=profile.supply=profile.enemyMemory=enabled;EditorUtility.SetDirty(profile);return profile;}
 public static void Run(){
  checks.Clear();var scene=EditorSceneManager.OpenScene("Assets/Scenes/Battle01.unity");var world=UnityEngine.Object.FindObjectOfType<BattleWorld>();var catalog=Load<UnitSymbolCatalog>("Assets/Resources/UnitSymbols.asset");
  var prefabWidths=new Dictionary<string,float>();foreach(var guid in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Game/Prefabs","Assets/Game/UnitLibrary/Prefabs"})){var path=AssetDatabase.GUIDToAssetPath(guid);var prefab=Load<GameObject>(path);var renderer=prefab.GetComponent<SpriteRenderer>();if(prefab.GetComponent<BattleUnit>()!=null&&renderer!=null)prefabWidths[path]=VisibleWidth(renderer.sprite)*Mathf.Abs(prefab.transform.localScale.x);}
  float reference=VisibleWidth(catalog.friendly[0]);for(int side=0;side<2;side++)for(int role=0;role<8;role++)for(int grade=0;grade<5;grade++){string name=(side==0?"Friendly_":"Enemy_")+Roles[role]+"_"+Grades[grade]+".png";string path=Root+name;float width=VisibleWidth(Load<Sprite>(path));Replace(path,Source+(side==0?"己方_蓝色/":"敌军_红色/")+Labels[role]+"/"+Labels[role]+"_"+ChineseGrades[grade]+".png",width);checks.Add("Preserved "+name+" width "+width);}
  foreach(var side in new[]{"Friendly","Enemy"}){string folder=side=="Friendly"?"己方_蓝色/":"敌军_红色/";string collector=Root+side+"_Collector.png";Replace(collector,Source+folder+"收集器/收集器.png",VisibleWidth(Load<Sprite>(collector)));Replace(Root+side+"_City.png",Source+folder+"城市/城市.png",reference*1.4f);}
  catalog.enemyUnknown=Replace(Root+"Enemy_Unknown.png",Source+"敌军_红色/未知单位/未知单位.png",VisibleWidth(catalog.enemy[0]));EditorUtility.SetDirty(catalog);
  foreach(var pair in prefabWidths){var g=PrefabUtility.LoadPrefabContents(pair.Key);var unit=g.GetComponent<BattleUnit>();var renderer=g.GetComponent<SpriteRenderer>();var identity=g.GetComponent<UnitSymbolIdentity>();if(identity==null)identity=g.AddComponent<UnitSymbolIdentity>();identity.catalog=catalog;renderer.sprite=catalog.Unit(unit.combatDefinition.role,unit.combatDefinition.echelon,unit.ownerId=="A");renderer.color=Color.white;float current=VisibleWidth(renderer.sprite)*Mathf.Abs(g.transform.localScale.x);g.transform.localScale*=pair.Value/current;PrefabUtility.SaveAsPrefabAsset(g,pair.Key);PrefabUtility.UnloadPrefabContents(g);}
  foreach(var side in new[]{"Friendly","Enemy"}){string path="Assets/Game/UnitLibrary/Prefabs/"+side+"/City.prefab";var g=PrefabUtility.LoadPrefabContents(path);g.transform.localScale=Vector3.one;g.GetComponent<SpriteRenderer>().sortingOrder=20;g.GetComponent<UnitSymbolIdentity>().citySortingOrder=20;PrefabUtility.SaveAsPrefabAsset(g,path);PrefabUtility.UnloadPrefabContents(g);}
  foreach(var city in UnityEngine.Object.FindObjectsOfType<RecoveryPoint>())if(city.kind==FacilityKind.RecoveryPoint){city.transform.localScale=Vector3.one;var identity=city.GetComponent<UnitSymbolIdentity>();if(identity==null)identity=city.gameObject.AddComponent<UnitSymbolIdentity>();identity.catalog=catalog;identity.citySortingOrder=20;var renderer=city.GetComponent<SpriteRenderer>();if(renderer!=null){renderer.sprite=city.ownerId=="A"?catalog.friendlyCity:catalog.enemyCity;renderer.color=Color.white;renderer.sortingOrder=20;}}
  var basic=Profile("PVE_BasicGuard",false);var enabled=Profile("PVE_EnabledModules",true);var patrol=Profile("PVE_PatrolRelief",false);patrol.patrol=patrol.reinforcement=patrol.cityRelief=true;var support=Profile("PVE_RecoverySupply",false);support.recovery=support.supply=true;
  var ai=world.GetComponent<BattleAIController>();ai.profile=basic;ai.autoToggleOnPlayerSwitch=true;ai.pauseWhenPlayerControlled=true;ai.playerId="B";ai.aiEnabled=true;ai.assignUnconfiguredUnits=true;
  var book=world.GetComponent<AITaskReservations>();if(book==null)book=world.gameObject.AddComponent<AITaskReservations>();ai.reservations=book;var intel=world.GetComponent<AIFactionIntel>();if(intel==null)intel=world.gameObject.AddComponent<AIFactionIntel>();intel.controller=ai;ai.intel=intel;
  foreach(var name in new[]{"InfantryRecovery_Squad","ResourceSupply_Squad"}){var path="Assets/Game/AIResponsePrefabs/"+name+".prefab";if(File.Exists(path)){var g=PrefabUtility.LoadPrefabContents(path);g.GetComponent<AIUnitOrder>().profileOverride=support;PrefabUtility.SaveAsPrefabAsset(g,path);PrefabUtility.UnloadPrefabContents(g);}}
  var armiesRoot=new GameObject("PvE observation armies");var oldUnits=UnityEngine.Object.FindObjectsOfType<BattleUnit>();foreach(var old in oldUnits)UnityEngine.Object.DestroyImmediate(old.gameObject);
  world.units=new BattleUnit[0];world.setup.sceneArmies=new ArmyRoadMover[0];var units=new List<BattleUnit>();var movers=new List<ArmyRoadMover>();var nodes=world.setup.roadMap.definition.nodes;
  for(int i=0;i<4;i++){float x=-14+i*4;int index=0;float best=float.MaxValue;for(int n=0;n<Mathf.Min(nodes.Length,34);n++){float score=Mathf.Abs(nodes[n].x-x);if(score<best){best=score;index=n;}}var center=world.setup.roadMap.transform.TransformPoint(nodes[index]);for(int side=0;side<2;side++){var position=center+Vector3.up*(side==0?1.2f:-1.2f);var prefab=Load<GameObject>("Assets/Game/UnitLibrary/Prefabs/"+(side==0?"Friendly":"Enemy")+"/Infantry_Platoon.prefab");var free=prefab.GetComponent<ArmyFreeMarchMover>();if(!world.setup.freeMarchMap.CanTraverse(new RoadPoint(position.x,position.y),new RoadPoint(position.x,position.y),free.AllowedTerrain))throw new Exception("Illegal observation spawn "+position);var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab);g.transform.SetParent(armiesRoot.transform,true);g.transform.position=position;g.name=(side==0?"蓝方":"红方")+"观察步兵"+(i+1);var u=g.GetComponent<BattleUnit>();u.unitId=(side==0?"A":"B")+"-observation-"+(i+1);u.designation=g.name;u.startingPersonnelPercent=100;units.Add(u);movers.Add(g.GetComponent<ArmyRoadMover>());if(side==1){var order=g.GetComponent<AIUnitOrder>();if(order==null)order=g.AddComponent<AIUnitOrder>();order.task=ai.defaultGuard;}}}
  world.units=units.ToArray();world.setup.sceneArmies=movers.ToArray();world.currentPlayer="A";var selection=world.GetComponent<ArmySelection>();if(selection==null)selection=world.gameObject.AddComponent<ArmySelection>();selection.armies=movers.ToArray();if(world.setup.tacticalDisplay!=null)world.setup.tacticalDisplay.armies=movers.ToArray();world.setup.zoomController.startAtMiddle=false;world.setup.mapCamera.orthographicSize=6;world.setup.mapCamera.transform.position=new Vector3(-8,1.5f,world.setup.mapCamera.transform.position.z);
  EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText("bold-symbol-preservation.txt",string.Join("\n",checks));Debug.Log("BOLD_SYMBOLS_PVE_INSTALLED: 85 symbols; widths preserved; city enlarged; basic B AI; 4 armies each side");
 }
}

